import{_ as a,o as r,a as e,b as i}from"./app.C41L12d5.js";const o="/ascendc.github.io/assets/vec_access.CunhvorL.png",l="/ascendc.github.io/assets/npu_3510_hw_arch_vector.DPLy9IhH.png",c="/ascendc.github.io/assets/a2a3_ub_memory_structure.BWoV4mJC.png",n="/ascendc.github.io/assets/ub_950.BmP-4x9h.png",m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Memory矢量计算","link":"/api/SIMD-API/basic_api/memory_vector_compute/memory_vector_compute"},{"text":"Vector逻辑架构","link":"/api/SIMD-API/basic_api/memory_vector_compute/Vector_logical_arch/Vector_logical_arch"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/memory_vector_compute/Vector_logical_arch/Vector_logical_arch.md","filePath":"api/SIMD-API/basic_api/memory_vector_compute/Vector_logical_arch/Vector_logical_arch.md","outlineHeaders":[{"level":2,"title":"Vector逻辑架构说明","slug":"Vector逻辑架构说明","link":"#Vector逻辑架构说明"},{"level":2,"title":"UB介绍","slug":"UB介绍","link":"#UB介绍"},{"level":3,"title":"UB的通用约束说明","slug":"UB的通用约束说明","link":"#UB的通用约束说明"},{"level":3,"title":"UB的内存结构与bank冲突","slug":"UB的内存结构与bank冲突","link":"#UB的内存结构与bank冲突"}],"lastUpdated":1788515292000}'),s={name:"api/SIMD-API/basic_api/memory_vector_compute/Vector_logical_arch/Vector_logical_arch.md"};function p(_,t,d,g,h,b){return r(),e("div",null,[...t[0]||(t[0]=[i('<div><article class="markdown-body"><h1>Vector逻辑架构<span id="ZH-CN_TOPIC_0000002573902865"></span></h1><h2 id="Vector逻辑架构说明">Vector逻辑架构说明<a class="header-anchor" href="#Vector逻辑架构说明">​</a></h2><p>Vector计算单元专用于执行向量计算。如下图所示，高亮部分展示了Vector计算单元及其关联的存储单元。</p><div data-filter="A3,910b"><ul><li><p>针对Atlas A3 训练系列产品/Atlas A3 推理系列产品、Atlas A2 训练系列产品/Atlas A2 推理系列产品，Vector逻辑架构如下图1所示。</p><p><strong>图1</strong> 向量计算单元架构图</p><p><img src="'+o+'" alt></p><p><strong>表1</strong> 向量计算单元关联的存储单元</p><table><thead><tr><th>存储单元</th><th>说明</th></tr></thead><tbody><tr><td>Unified Buffer（UB）</td><td>AI Core内部物理存储单元，通常用于存储向量计算的输入/输出数据。</td></tr></tbody></table></li></ul></div><div data-filter="950"><ul><li><p>针对Ascend 950PR/Ascend 950DT，Vector逻辑架构如下图2所示。</p><p><strong>图2</strong> 向量计算单元架构图</p><p><img src="'+l+'" alt></p><p><strong>表2</strong> 向量计算单元关联的存储单元</p><table><thead><tr><th>存储单元</th><th>说明</th></tr></thead><tbody><tr><td>UB</td><td>AI Core内部物理存储单元，通常用于存储向量计算的输入/输出数据。</td></tr><tr><td>SIMD Register File</td><td>AI Core内部物理存储单元，在SIMD程序中，数据从UB搬运到Register进行计算，产生的中间结果可以不用传回UB，直接在寄存器计算。</td></tr></tbody></table></li></ul></div><h2 id="UB介绍">UB介绍<span id="ZH-CN_TOPIC_0000002574022839"></span><a class="header-anchor" href="#UB介绍">​</a></h2><h3 id="UB的通用约束说明">UB的通用约束说明<a class="header-anchor" href="#UB的通用约束说明">​</a></h3><ul><li>UB地址对齐约束，请参考<a href="../../../general_description_and_constraints.html#%E9%80%9A%E7%94%A8%E5%9C%B0%E5%9D%80%E5%AF%B9%E9%BD%90%E7%BA%A6%E6%9D%9F">通用地址对齐约束</a>。</li><li>UB地址重叠约束，请参考<a href="../../../general_description_and_constraints.html#%E9%80%9A%E7%94%A8%E5%9C%B0%E5%9D%80%E9%87%8D%E5%8F%A0%E7%BA%A6%E6%9D%9F">通用地址重叠约束</a>。</li></ul><h3 id="UB的内存结构与bank冲突">UB的内存结构与bank冲突<a class="header-anchor" href="#UB的内存结构与bank冲突">​</a></h3><p>为了提高数据访问的效率和吞吐量，UB采用了大小相等的内存模块（bank）结构设计。当多条读写指令同时访问UB时，由于硬件资源的限制，这些指令不能同时执行，从而引发bank冲突。在这种情况下，指令需要排队等待资源，无法在一个指令周期内完成。</p><div data-filter="A3,910b"><ul><li>针对Atlas A3 训练系列产品/Atlas A3 推理系列产品、Atlas A2 训练系列产品/Atlas A2 推理系列产品 <ul><li><p>UB的内存结构</p><p><strong>图3</strong> UB的内存结构图</p><p><img src="'+c+'" alt></p><p>如图3所示，UB总大小为192KB，包含16个bank group（BG0 ~ BG15），每个bank group包含3个bank。每个bank大小为4KB，由128行组成，每行长度为32B。</p><ul><li><strong>读写冲突</strong>：读操作和写操作同时尝试访问同一个bank。</li><li><strong>写写冲突</strong>：多个写操作同时尝试访问同一个bank group。</li><li><strong>读读冲突</strong>：多个读操作同时尝试访问同一个bank group。</li></ul></li><li><p>bank冲突优化</p><p>可参考<a href="../../../../../guide/operator_practice/simd_operator_optimization/memory_access/avoid_ub_bank_conflict/avoid_bank_conflict_npu_arch_2201.html">避免bank冲突（NPU架构版本2201）</a>。</p></li></ul></li></ul></div><div data-filter="950"><ul><li>针对Ascend 950PR/Ascend 950DT <ul><li><p>UB的内存结构</p><p><strong>图4</strong> UB的内存结构图</p><p><img src="'+n+'" alt></p><p>如图4所示，UB总大小为256KB，包含8个bank group（BG0 ~ BG7），每个bank group包含2个bank。每个bank大小为16KB，由512行组成，每行长度为32B。</p><ul><li><strong>读写冲突</strong>：读操作和写操作同时尝试访问同一个bank。</li><li><strong>写写冲突</strong>：多个写操作同时尝试访问同一个bank group。</li><li><strong>读读冲突</strong>：两个读操作同时尝试访问同一个bank，或者两个以上读操作同时尝试访问同一个bank group。</li></ul></li><li><p>bank冲突优化</p><p>可参考<a href="../../../../../guide/operator_practice/simd_operator_optimization/memory_access/avoid_ub_bank_conflict/avoid_bank_conflict_npu_arch_3510.html">避免bank冲突（NPU架构版本3510）</a>。</p></li></ul></li></ul></div></article></div>',1)])])}const B=a(s,[["render",p]]);export{m as __pageData,B as default};
